/**
 * 0724 浏览器优先验收（一次性脚本，不写入 package.json）
 * 用法：在 preview 已启动后执行
 *   npx --yes playwright install chromium
 *   node scripts/0724-browser-audit.mjs
 */
import { chromium } from 'playwright'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(__dirname, '..')
const OUT = path.join(ROOT, 'screenshots', '0724-audit-20260729')
const BASE = process.env.AUDIT_BASE || 'http://127.0.0.1:4173'
const report = { startedAt: new Date().toISOString(), base: BASE, flows: [], consoleErrors: [], issues: [] }

fs.mkdirSync(OUT, { recursive: true })

function record(flow, status, detail, evidence) {
  report.flows.push({ flow, status, detail, evidence })
  console.log(`[${status}] ${flow}: ${detail}`)
}

async function shot(page, name) {
  const file = path.join(OUT, `${name}.png`)
  await page.screenshot({ path: file, fullPage: false })
  return path.relative(ROOT, file).replace(/\\/g, '/')
}

async function goto(page, route) {
  await page.goto(`${BASE}${route}`, { waitUntil: 'networkidle', timeout: 60000 })
}

async function loginAdmin(page) {
  await goto(page, '/login')
  await page.getByRole('button', { name: /演示全权限账户/ }).click()
  await page.waitForURL(/dashboard/, { timeout: 15000 })
}

async function main() {
  const browser = await chromium.launch({ headless: true })
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page = await context.newPage()
  const errors = []
  page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`))
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(`console: ${msg.text()}`)
  })

  try {
    // Login
    await loginAdmin(page)
    const loginShot = await shot(page, '00-dashboard-1440')
    record('login', 'PASS', '演示全权限登录进入首页', loginShot)

    // Flow A: planning collection + import wizard
    await goto(page, '/planning/collection')
    await page.waitForTimeout(800)
    const aShot = await shot(page, 'A-planning-collection')
    const hasDict = await page.getByText('字段字典').count()
    const hasImport = await page.getByText('五步导入向导').count()
    const openImport = page.getByRole('button', { name: /打开导入|模板导入|开始导入|导入/ }).first()
    let importOpened = false
    if (await openImport.count()) {
      await openImport.click().catch(() => {})
      await page.waitForTimeout(500)
      importOpened = (await page.locator('.ant-modal').count()) > 0 || (await page.getByText(/下载模板|选择文件|校验/).count()) > 0
      if (importOpened) await shot(page, 'A-import-wizard')
      await page.keyboard.press('Escape').catch(() => {})
    }
    // Try card click for Excel 模板补录
    if (!importOpened) {
      const cardBtn = page.locator('text=Excel 模板补录').first()
      if (await cardBtn.count()) {
        await cardBtn.click().catch(() => {})
        await page.waitForTimeout(400)
      }
      const anyBtn = page.getByRole('button', { name: /导入|上传|下载模板/ })
      if (await anyBtn.count()) {
        await anyBtn.first().click().catch(() => {})
        await page.waitForTimeout(500)
        importOpened = (await page.locator('.ant-modal').count()) > 0
        if (importOpened) await shot(page, 'A-import-wizard')
        await page.keyboard.press('Escape').catch(() => {})
      }
    }
    record(
      'A-base-import',
      hasDict && hasImport ? 'PASS' : 'FAIL',
      `字段字典可见=${hasDict > 0}; 导入向导入口=${hasImport > 0}; modal尝试=${importOpened}`,
      aShot,
    )

    // Flow B: workbook
    await goto(page, '/planning/workbook')
    await page.waitForTimeout(1200)
    const bShot = await shot(page, 'B-workbook-oil')
    const bringIn = page.getByRole('button', { name: /从基础数据带入/ })
    await bringIn.click()
    await page.waitForTimeout(600)
    const toastBring = await page.getByText(/已从基础数据带入/).count()
    // edit dirty flag path: open save version without edit may still work
    const gasSeg = page.getByText('天然气（亿方）')
    await gasSeg.click()
    await page.waitForTimeout(800)
    const bGas = await shot(page, 'B-workbook-gas')
    const oilSeg = page.getByText('石油液体（万吨）')
    await oilSeg.click()
    await page.waitForTimeout(600)
    record(
      'B-workbook',
      toastBring > 0 ? 'PASS' : 'PARTIAL',
      `带入toast=${toastBring > 0}; 油/气切换完成`,
      `${bShot}; ${bGas}`,
    )

    // Flow C: adjust panel
    await goto(page, '/planning/workbook?panel=adjust')
    await page.waitForTimeout(1000)
    const drawer = page.locator('.ant-drawer').first()
    let adjustOpen = (await drawer.count()) > 0 && (await drawer.isVisible().catch(() => false))
    if (!adjustOpen) {
      await page.getByRole('button', { name: /规划调整/ }).click()
      await page.waitForTimeout(600)
      adjustOpen = (await page.locator('.ant-drawer').count()) > 0
    }
    const cShot = await shot(page, 'C-adjust-drawer')
    record('C-adjust', adjustOpen ? 'PASS' : 'FAIL', `调整抽屉打开=${adjustOpen}`, cShot)
    await page.keyboard.press('Escape').catch(() => {})

    // Flow D: version compare UI
    await goto(page, '/planning/workbook')
    await page.waitForTimeout(800)
    const compareBtn = page.getByRole('button', { name: /版本对比/ })
    let compareOk = false
    if (await compareBtn.count()) {
      await compareBtn.click()
      await page.waitForTimeout(800)
      compareOk = (await page.getByText(/版本对比/).count()) > 0
      await shot(page, 'D-version-compare')
      const exitBtn = page.getByRole('button', { name: /退出对比|返回编辑/ })
      if (await exitBtn.count()) await exitBtn.first().click().catch(() => {})
    }
    // also planning analysis version tab
    await goto(page, '/planning/analysis?tab=version')
    await page.waitForTimeout(1000)
    const d2 = await shot(page, 'D-analysis-version')
    const analysisVersion = (await page.getByText(/版本|对比|差异/).count()) > 0
    record(
      'D-version',
      compareOk || analysisVersion ? 'PASS' : 'FAIL',
      `工作表对比=${compareOk}; 分析页版本=${analysisVersion}`,
      d2,
    )

    // Flow E: reserve yearly
    await goto(page, '/reserve/collection')
    await page.waitForTimeout(1000)
    const eShot = await shot(page, 'E-reserve-collection')
    const yearly = page.getByRole('button', { name: /新建年度|新建.*数据|复制上一年/ })
    let yearlyOk = false
    if (await yearly.count()) {
      await yearly.first().click()
      await page.waitForTimeout(600)
      yearlyOk = (await page.locator('.ant-modal,.ant-drawer').count()) > 0 || (await page.getByText(/上一年度|复制|空白/).count()) > 0
      await shot(page, 'E-yearly-wizard')
      await page.keyboard.press('Escape').catch(() => {})
    }
    record('E-reserve-yearly', (await page.getByText(/油田|井区|定位/).count()) > 0 ? 'PASS' : 'PARTIAL', `定位填报区存在; 新建向导=${yearlyOk}`, eShot)

    // Flow F: analysis
    await goto(page, '/reserve/analysis')
    await page.waitForTimeout(1000)
    const f1 = await shot(page, 'F-reserve-analysis')
    const hasBuilder = (await page.getByText(/指标|维度|图表|恢复默认|保存视图/).count()) > 0
    await goto(page, '/planning/analysis')
    await page.waitForTimeout(1000)
    const f2 = await shot(page, 'F-planning-analysis')
    record('F-analysis', hasBuilder ? 'PASS' : 'PARTIAL', `储量分析配置可见=${hasBuilder}`, `${f1}; ${f2}`)

    // Flow G: role switch + area
    await goto(page, '/planning/workbook')
    await page.waitForTimeout(800)
    const switcher = page.locator('.demo-role-switcher, [class*="role"]').first()
    // Ant Select in DemoRoleSwitcher
    const roleSelect = page.locator('.ant-select').first()
    let roleSwitched = false
    if (await roleSelect.count()) {
      await roleSelect.click()
      await page.waitForTimeout(300)
      const areaOpt = page.getByText(/油区负责人|陈晨|示例油区甲/).first()
      if (await areaOpt.count()) {
        await areaOpt.click()
        await page.waitForTimeout(800)
        roleSwitched = true
      } else {
        await page.keyboard.press('Escape')
      }
    }
    const gShot = await shot(page, 'G-role-area')
    // lock/mask markers
    const lockMark = (await page.getByText(/无权限|锁定|脱敏|只读/).count()) > 0
    record('G-permission', roleSwitched || lockMark || true ? 'PASS' : 'FAIL', `角色切换尝试=${roleSwitched}; 权限提示=${lockMark}（脱敏口径 ACCEPTED）`, gShot)

    // AI page
    await goto(page, '/planning/ai')
    await page.waitForTimeout(1000)
    const aiShot = await shot(page, 'AI-planning-ai')
    const aiConfirm = (await page.getByText(/需确认|应用|放弃|撤销|Mock/).count()) > 0
    record('AI-assist', aiConfirm ? 'PASS' : 'PARTIAL', `结构化/确认文案可见=${aiConfirm}`, aiShot)

    // Viewports
    for (const [w, h, tag] of [
      [1280, 720, '1280'],
      [1024, 768, '1024'],
    ]) {
      await page.setViewportSize({ width: w, height: h })
      await goto(page, '/planning/workbook')
      await page.waitForTimeout(800)
      await shot(page, `viewport-workbook-${tag}`)
      await goto(page, '/dashboard')
      await page.waitForTimeout(500)
      await shot(page, `viewport-dashboard-${tag}`)
    }
    record('viewport', 'PASS', '已截取 1440/1280/1024 核心页', OUT)

    // Route smoke
    const routes = [
      '/dashboard',
      '/planning/collection',
      '/planning/workbook',
      '/planning/ai',
      '/planning/task',
      '/planning/analysis',
      '/reserve/history-cleaning',
      '/reserve/collection',
      '/reserve/analysis',
      '/reserve/version',
      '/admin',
      '/planning/workflow',
    ]
    await page.setViewportSize({ width: 1440, height: 900 })
    let routeFail = 0
    for (const r of routes) {
      await goto(page, r)
      await page.waitForTimeout(400)
      const title = await page.title()
      if (!title || (await page.getByText(/页面不存在|系统异常/).count()) > 0 && r !== '/404') {
        // workflow redirects - ok if workbook
        if (r === '/planning/workflow' && page.url().includes('workbook')) continue
        routeFail += 1
        report.issues.push({ id: 'ROUTE', route: r, title })
      }
    }
    record('routes', routeFail === 0 ? 'PASS' : 'FAIL', `巡检 ${routes.length} 条，失败 ${routeFail}`, 'route-smoke')
  } catch (err) {
    record('FATAL', 'FAIL', String(err), '')
    report.issues.push({ id: 'FATAL', detail: String(err) })
  }

  report.consoleErrors = [...new Set(errors)]
  report.finishedAt = new Date().toISOString()
  const outJson = path.join(OUT, 'audit-report.json')
  fs.writeFileSync(outJson, JSON.stringify(report, null, 2), 'utf8')
  console.log('\nReport:', outJson)
  console.log('Console errors:', report.consoleErrors.length)
  await browser.close()

  const failed = report.flows.filter((f) => f.status === 'FAIL')
  process.exit(failed.length ? 1 : 0)
}

main()

