/**
 * 油/气区名称对齐：天然气种子可用「示例气区甲」，账号 scope 多为「示例油区甲」。
 * Demo 约定：气区甲 ≡ 油区甲（按甲/乙后缀对齐），避免切天然气后权限全锁死。
 */
export function normalizeAreaKey(area: string) {
  return area.replace(/气区/g, '油区').trim()
}

export function areaInUserScope(user: DemoUser | null | undefined, area: string) {
  if (!user) return false
  if (!user.areaScope.length) return true
  const key = normalizeAreaKey(area)
  return user.areaScope.some((item) => item === area || normalizeAreaKey(item) === key)
}

export function filterByScope<T extends { area?: string; oilfield?: string }>(records: T[], user: DemoUser | null | undefined) {
  if (!user) return []
  return records.filter((record) => {
    const areaAllowed = !user.areaScope.length || (record.area ? areaInUserScope(user, record.area) : false)
    const fieldAllowed = !user.fieldScope.length || (record.oilfield && user.fieldScope.includes(record.oilfield))
    return Boolean(areaAllowed && fieldAllowed)
  })
}

/** 是否可编辑指定油区数据（Sheet11-17 按油区管控：公司级可编辑全部，油区角色仅本油区） */
export function canEditArea(user: DemoUser | null | undefined, area: string) {
  if (!user) return false
  if (!canPerformAction(user, 'edit')) return false
  return areaInUserScope(user, area)
}

/** 是否可查看指定油区数据（无权限数据在页面上脱敏或只读展示） */
export function canViewArea(user: DemoUser | null | undefined, area: string) {
  if (!user) return false
  return areaInUserScope(user, area)
}

