import { describe, expect, it } from 'vitest'
import { mockUsers } from '../src/mock/users'
import { canEditField, canPerformAction, canVisitPath, filterByScope, getVisibleRoutes } from '../src/mock/permissions'

describe('mock permission framework', () => {
  const byId = (id: string) => mockUsers.find((item) => item.id === id)!

  it('shows role-specific menus and protects direct URLs', () => {
    expect(getVisibleRoutes(byId('u-area'))).toEqual(['dashboard', 'planning'])
    expect(canVisitPath(byId('u-area'), '/reserve/collection')).toBe(false)
    expect(canVisitPath(byId('u-manager'), '/planning/analysis')).toBe(true)
    expect(canVisitPath(byId('u-manager'), '/planning/version')).toBe(true)
    expect(canVisitPath(byId('u-admin'), '/planning/workflow')).toBe(false)
  })

  it('uses a full-access account as the default demonstration identity', () => {
    const demoAdmin = byId('u-demo-admin')
    expect(mockUsers[0].id).toBe('u-demo-admin')
    expect(getVisibleRoutes(demoAdmin)).toEqual(['dashboard', 'reserve', 'planning', 'admin'])
    expect(canVisitPath(demoAdmin, '/planning/workflow')).toBe(true)
    expect(canPerformAction(demoAdmin, 'configure')).toBe(true)
    expect(canPerformAction(demoAdmin, 'publish')).toBe(true)
  })

  it('limits actions and editable fields by identity', () => {
    expect(canPerformAction(byId('u-field'), 'submit')).toBe(true)
    expect(canPerformAction(byId('u-field'), 'publish')).toBe(false)
    expect(canEditField(byId('u-field'), 'planning.base')).toBe(true)
    expect(canEditField(byId('u-field'), 'planning.total')).toBe(false)
    expect(canPerformAction(byId('u-manager'), 'edit')).toBe(false)
  })

  it('filters oilfield data to the user scope', () => {
    const records = [{ area: '示例油区甲', oilfield: '示例油田甲' }, { area: '示例油区乙', oilfield: '示例油田乙' }]
    expect(filterByScope(records, byId('u-area'))).toHaveLength(1)
    expect(filterByScope(records, byId('u-field'))).toEqual([records[0]])
  })
})

  it('无变化行标记为 same', () => {
    const rows = [makeRow({ id: 'a' })]
    const diffs = diffVersionRows(rows, [makeRow({ id: 'a' })])
    expect(diffs[0].changeType).toBe('same')
  })
})

